<?php
declare(strict_types=1);require_once __DIR__.'/../config/conexion.php';require_once __DIR__.'/../includes/seguridad.php';require_once __DIR__.'/../includes/permisos.php';require_once __DIR__.'/../models/MgSeguimientoModel.php';require_once __DIR__.'/../models/MgBitacoraModel.php';require_role(['administrador','coordinador_mg','auxiliar_mg']);requerir_permiso('mg.alertas.ver');$m=new MgSeguimientoModel($pdo);$bit=new MgBitacoraModel($pdo);if(($_GET['accion']??'')==='atender'&&$_SERVER['REQUEST_METHOD']==='POST'){validar_csrf();$tipo=trim($_POST['tipo_alerta']);$id=(int)$_POST['id_referencia'];$nota=trim($_POST['nota']);if($nota===''){flash('error','La nota de atención es obligatoria.');}else{$s=$pdo->prepare('INSERT INTO alertas_atendidas(tipo_alerta,id_referencia,atendida_por,nota) VALUES(?,?,?,?)');$s->execute([$tipo,$id,$_SESSION['id_usuario'],$nota]);$bit->registrar('atender_alerta','alertas_atendidas',(int)$pdo->lastInsertId(),null,['tipo_alerta'=>$tipo,'id_referencia'=>$id,'nota'=>$nota]);flash('success','Alerta marcada como atendida.');}redir('/controllers/mg_alertas.php');}$alertas=$m->alertas();$filtradas=[];foreach($alertas as $a){if(!$m->atendida($a['tipo'],$a['id']))$filtradas[]=$a;}$tituloPagina='Panel de alertas MG';require __DIR__.'/../views/mg/alertas/index.php';
